def count_stepping_numbers(low: str, high: str) -> int:
    MOD = 10**9 + 7

    def count_up_to(s: str) -> int:
        """Count stepping numbers from 1 to int(s) inclusive."""
        n = len(s)
        # dp[length][digit][tight][started]
        # We'll use memoization with recursion
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dfs(pos, digit, tight, started):
            """
            pos: current position (0-indexed)
            digit: last digit used (0-9), or -1 if not started
            tight: whether we are still matching the prefix of s
            started: whether we have started the number (no leading zero)
            """
            if pos == n:
                return 1 if started else 0

            limit = int(s[pos]) if tight else 9
            count = 0
            for d in range(0, limit + 1):
                new_tight = tight and (d == limit)
                if not started:
                    if d == 0:
                        # Don't start yet
                        count = (count + dfs(pos + 1, -1, new_tight, False)) % MOD
                    else:
                        # Start with d
                        count = (count + dfs(pos + 1, d, new_tight, True)) % MOD
                else:
                    # Already started, check if d is a valid next digit
                    if abs(d - digit) == 1:
                        count = (count + dfs(pos + 1, d, new_tight, True)) % MOD
                    else:
                        # Skip this digit
                        pass
            return count % MOD

        return dfs(0, -1, True, False)

    def compare(a: str, b: str) -> int:
        """Compare two strings as numbers. Return -1 if a < b, 0 if a == b, 1 if a > b."""
        if len(a) != len(b):
            return -1 if len(a) < len(b) else 1
        for i in range(len(a)):
            if a[i] < b[i]:
                return -1
            elif a[i] > b[i]:
                return 1
        return 0

    # Count up to high, then subtract count up to low-1
    high_count = count_up_to(high)

    # Compute low - 1
    low_int = int(low)
    if low_int <= 1:
        low_minus_one_count = 0
    else:
        low_minus_one = str(low_int - 1)
        low_minus_one_count = count_up_to(low_minus_one)

    result = (high_count - low_minus_one_count) % MOD
    return result
